import { useCallback, useEffect, useMemo, useState } from "react";
import { Navigate, Route, Routes, useLocation, useNavigate } from "react-router-dom";
import { createTranslator } from "@dcortex/canvas-format";
import { OpsMenuDoc } from "@dcortex/contracts";
import { createApiClient, type ApiClient } from "../api/client.js";
import { messages } from "../i18n/messages.js";
import { sessionAccess } from "../navPermissions.js";
import { setRailAccess } from "../railAccess.js";
import { applyStoredLocale, localeOptions, switchLocale } from "../viewerLocale.js";
import { Landing } from "../screens/Landing.js";
import { SessionExpiryGuard } from "../SessionExpiryGuard.js";
import { DCORTEX_MARK } from "../brand.js";
import { TenantMark } from "./TenantMark.js";
import { performLogout } from "../ConsoleControls.js";
import { roleName } from "../roleNames.js";
import { Launchpad } from "./Launchpad.js";
import { Operations } from "./Operations.js";
import { Radar } from "./Radar.js";
import { clearRadarSessionCache } from "./radarSessionCache.js";
import { Rules } from "./Rules.js";
import { rememberOpsMenu, readRememberedOpsMenu } from "./opsMenuMemory.js";
import { TopMenu } from "./TopMenu.js";

/** The Operations Control Panel console shell (knowledge-base/features/ops-control-panel.md §5) — a third Vite entry of
 * this app, served by the airline BFF under /ops. Same client lifecycle as the current console: 401 → /login keeping
 * the deep link, the version-skew banner, a contextHash change remounting server state. */

declare const __BUILD_ID__: string | undefined;
const BUILD_ID = typeof __BUILD_ID__ === "string" ? __BUILD_ID__ : "dev";
const SESSION_RETRY_MS = 30_000;
/** A full navigation, so the signed-out client keeps no session state in memory. */
const toOpsLogin = () => window.location.assign("/ops/login");

export function OpsApp({ client: injected, afterSignOut = toOpsLogin }: { client?: ApiClient; afterSignOut?: () => void }) {
  const navigate = useNavigate();
  const location = useLocation();
  const [skew, setSkew] = useState<string | undefined>();
  const [epoch, setEpoch] = useState(0);

  const client = useMemo(() => {
    const c =
      injected ??
      createApiClient({
        buildId: BUILD_ID,
        onUnauthenticated: () => navigate(`/login?returnTo=${encodeURIComponent(location.pathname + location.search)}`),
        onContextChange: () => {
          clearRadarSessionCache();
          setEpoch((e) => e + 1);
        },
        onVersionSkew: (server) => setSkew(server),
      });
    applyStoredLocale(c); // the remembered language rides the very first request
    return c;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [injected]);

  // The session seam carries the tenant's display name and languages in its body (the envelope's presentation context
  // arrives with the first data read, which the screen also reports).
  const [customer, setCustomer] = useState(client.presentation()?.customerName ?? "");
  const [languages, setLanguages] = useState<{ code: string; label: string }[]>([]);
  // Who is signed in, from the same probe: two accounts in one browser share the session cookie, so the header names it.
  const [user, setUser] = useState<{ subject: string; roles: readonly string[] } | undefined>();
  // The admin-configured menu. A reply this console does not recognise draws the built-in menu.
  // Paint the menu this browser last applied, in the first frame. The session probe confirms it; until this
  // browser has applied one, the bar stays empty rather than flashing the built-in entries.
  const [opsMenu, setOpsMenu] = useState<OpsMenuDoc | undefined>(() => readRememberedOpsMenu()?.doc);
  const [menuReady, setMenuReady] = useState(() => readRememberedOpsMenu() !== undefined);
  // A failed probe (a restarting server, a dropped connection) is retried until one answers: the header's languages
  // and the menu's access rule come only from it, and nothing else would ask again.
  useEffect(() => {
    let live = true;
    let retry: ReturnType<typeof setTimeout> | undefined;
    const probe = () =>
      client.get<{ subject?: string; roles?: string[]; presentation?: { customerName?: string; supportedLocales?: string[]; opsMenu?: unknown } }>("/api/auth/session").then(
        (body) => {
          if (!live) return;
          setRailAccess(sessionAccess(body));
          setUser(body?.subject ? { subject: body.subject, roles: body.roles ?? [] } : undefined);
          setCustomer(body?.presentation?.customerName ?? client.presentation()?.customerName ?? "");
          setLanguages(localeOptions(body?.presentation?.supportedLocales ?? []));
          const menu = OpsMenuDoc.safeParse(body?.presentation?.opsMenu);
          setOpsMenu(menu.success ? menu.data : undefined);
          rememberOpsMenu(menu.success ? menu.data : null);
          setMenuReady(true);
        },
        () => {
          if (!live) return;
          setRailAccess({ state: "unknown" });
          // A failed probe has no stored menu to apply. The built-in menu is the safe default, and a later
          // failure must not wipe a menu a previous probe already applied.
          setMenuReady(true);
          retry = setTimeout(probe, SESSION_RETRY_MS);
        },
      );
    void probe();
    return () => {
      live = false;
      if (retry) clearTimeout(retry);
    };
  }, [client, epoch]);

  const t = createTranslator(client.presentation()?.locale ?? "en", messages);
  // the customer's name arrives with the first data read of whichever screen is open
  const syncCustomer = useCallback(() => setCustomer(client.presentation()?.customerName ?? ""), [client]);
  const onLoggedIn = useCallback(() => {
    const returnTo = new URLSearchParams(location.search).get("returnTo") ?? "/";
    navigate(returnTo.startsWith("/login") ? "/" : returnTo);
  }, [location.search, navigate]);

  const onLogin = location.pathname === "/login";
  const [theme, setTheme] = useState<"dark" | "light">(() => (document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark"));
  const toggleTheme = () => {
    const next = theme === "dark" ? "light" : "dark";
    document.documentElement.setAttribute("data-theme", next);
    setTheme(next);
  };

  return (
    <div className="ops-app">
      {skew && <div className="banner">{t("app.versionSkew", { build: skew })}</div>}
      {!onLogin && <SessionExpiryGuard client={client} />}
      {!onLogin && (
        <header className="ops-header">
          <span className="ops-brand" data-testid="ops-brand">
            <img className="ops-logo" src={DCORTEX_MARK} alt={t("ops.logoAlt")} data-testid="ops-logo" />
            <TenantMark className="ops-tenant-logo" alt={t("shell.tenantLogo")} />
            <span>{t("ops.brand", { customer })}</span>
          </span>
          <TopMenu t={t} locale={client.presentation()?.locale ?? "en"} settings={opsMenu} pending={!menuReady} />
          <button type="button" className="ops-theme" data-testid="ops-theme" aria-label={t("ops.toggleTheme")} aria-pressed={theme === "light"} onClick={toggleTheme}>
            {theme === "dark" ? "☀" : "☾"}
          </button>
          {languages.length > 1 && (
            <span className="ops-lang" role="group" aria-label={t("ops.language")}>
              {languages.map((l) => (
                <button
                  key={l.code}
                  type="button"
                  data-testid={`ops-lang-${l.code}`}
                  aria-pressed={l.code === (client.presentation()?.locale ?? "")}
                  onClick={() => void switchLocale(client, l.code)}
                >
                  {l.label}
                </button>
              ))}
            </span>
          )}
          {user && (
            <span className="ops-user" data-testid="ops-user" aria-label={t("ops.user.signedInAs", { user: user.subject })}>
              <span className="ops-user-name" data-testid="ops-user-name">{user.subject}</span>
              <span className="ops-user-roles" data-testid="ops-user-roles">{user.roles.map((r) => roleName(t, r)).join(", ")}</span>
              <button type="button" data-testid="ops-sign-out" onClick={() => void performLogout(client, afterSignOut)}>
                {t("shell.logout")}
              </button>
            </span>
          )}
        </header>
      )}
      <Routes>
        <Route path="/login" element={<Landing client={client} onLoggedIn={onLoggedIn} />} />
        <Route path="/" element={<Navigate to="/radar" replace />} />
        <Route path="/operations" element={<Operations key={epoch} client={client} onPresentation={syncCustomer} />} />
        <Route path="/radar" element={<Radar key={epoch} client={client} onPresentation={syncCustomer} onUnauthenticated={() => navigate(`/login?returnTo=${encodeURIComponent("/radar")}`)} />} />
        <Route path="/launchpad" element={<Launchpad key={epoch} client={client} onPresentation={syncCustomer} />} />
        <Route path="/rules" element={<Rules key={epoch} client={client} />} />
        <Route path="/fleet" element={<p className="ops-placeholder" data-testid="ops-fleet-placeholder">{t("ops.fleet.placeholder")}</p>} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </div>
  );
}
